+      height: 18px;
+      accent-color: var(--accent);
+      flex: none;
+    }
+
+    .choice span {
+      line-height: 1.45;
+    }
+
+    .actions {
+      display: flex;
+      justify-content: flex-end;
+      padding-top: 24px;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      padding: 14px 22px;
+      background: linear-gradient(135deg, var(--accent), #9b7bff);
+      color: white;
+      font: inherit;
+      font-weight: 700;
