<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #11182c;
      --panel-2: #18223d;
      --text: #e8eefc;
      --muted: #a7b4d6;
      --accent: #7c9cff;
      --accent-2: #6ee7c8;
      --border: rgba(148, 163, 184, 0.22);
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.38);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 35%),
        linear-gradient(180deg, #08101f 0%, #0b1020 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .app {
      width: min(920px, 100%);
    }

    .quiz-shell {
      background: linear-gradient(180deg, rgba(17, 24, 44, 0.94), rgba(11, 16, 32, 0.98));
      border: 1px solid var(--border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .quiz-header {
      padding: 32px 32px 20px;
      border-bottom: 1px solid var(--border);
      background: linear-gradient(180deg, rgba(30, 41, 73, 0.7), rgba(17, 24, 44, 0));
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent-2);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.8rem, 2.6vw, 2.5rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 12px 0 0;
      color: var(--muted);
      max-width: 60ch;
      line-height: 1.6;
    }

    form {
      padding: 10px 32px 32px;
    }

    .form-field {
      margin-top: 22px;
      padding: 22px;
      background: linear-gradient(180deg, rgba(24, 34, 61, 0.9), rgba(17, 24, 44, 0.9));
      border: 1px solid var(--border);
      border-radius: 18px;
    }

    .question-title {
      margin: 0 0 8px;
      font-size: 1.1rem;
      line-height: 1.4;
    }

    .help-text {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.55;
    }

    .choices {
      display: grid;
      gap: 12px;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      border-radius: 14px;
      border: 1px solid rgba(148, 163, 184, 0.18);
      background: rgba(8, 16, 31, 0.45);
      transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
    }

    .choice:hover,
    .choice:focus-within {
      transform: translateY(-1px);
      border-color: rgba(124, 156, 255, 0.55);
      background: rgba(22, 32, 60, 0.75);
    }

    .choice input {
      margin-top: 3px;
      width: 18px;
      height: 18px;
      accent-color: var(--accent);
      flex: none;
    }

    .choice span {
      line-height: 1.45;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      padding-top: 24px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      background: linear-gradient(135deg, var(--accent), #9b7bff);
      color: white;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(124, 156, 255, 0.3);
      transition: transform 0.15s ease, filter 0.15s ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.05);
    }

    button:focus-visible,
    input:focus-visible {
      outline: 3px solid rgba(110, 231, 200, 0.95);
      outline-offset: 2px;
    }

    .result {
      margin-top: 18px;
      color: var(--muted);
      min-height: 1.5em;
    }

    @media (max-width: 640px) {
      .quiz-header,
      form {
        padding-left: 18px;
        padding-right: 18px;
      }

      .form-field {
        padding: 18px;
      }
    }
  </style>
</head>
<body>
  <div class="app" id="root"></div>

  <script>
    const quizData = [
      {
        id: 'q1',
        prompt: 'Which of these are programming languages?',
        helpText: 'Select every option that is a language used to write software.',
        choices: [
          'Python',
          'HTML',
          'JavaScript',
          'CSS'
        ]
      },
      {
        id: 'q2',
        prompt: 'Which of these are commonly used for system-level programming?',
        choices: [
          'Rust',
          'C',
          'Photoshop',
          'Go'
        ]
      },
      {
        id: 'q3',
        prompt: 'Which of these are scripting or interpreted languages?',
        choices: [
          'Ruby',
          'TypeScript',
          'Assembly',
          'PHP'
        ]
      }
    ];

    function Choice({ name, id, text }) {
      return `
        <label class="choice" for="${id}">
          <input type="checkbox" id="${id}" name="${name}" value="${text}">
          <span>${text}</span>
        </label>
      `;
    }

    function Question({ id, prompt, helpText, choices }, index) {
      return `
        <div class="form-field">
          <fieldset>
            <legend class="question-title">${index + 1}. ${prompt}</legend>
            ${helpText ? `<p class="help-text">${helpText}</p>` : ''}
            <div class="choices" role="group" aria-label="${prompt}">
              ${choices.map((choice, choiceIndex) =>
                Choice({
                  name: id,
                  id: `${id}-${choiceIndex}`,
                  text: choice
                })
              ).join('')}
            </div>
          </fieldset>
        </div>
      `;
    }

    function QuizApp() {
      return `
        <section class="quiz-shell" aria-labelledby="quiz-title">
          <header class="quiz-header">
            <p class="eyebrow">Knowledge Check</p>
            <h1 id="quiz-title">Computer Languages Quiz</h1>
            <p class="subtitle">Choose all answers that apply for each question, then submit your selections.</p>
          </header>
          <form id="quiz-form">
            ${quizData.map((question, index) => Question(question, index)).join('')}
            <div class="actions">
              <button type="submit">Submit Quiz</button>
            </div>
            <p class="result" id="result" aria-live="polite"></p>
          </form>
        </section>
      `;
    }

    document.getElementById('root').innerHTML = QuizApp();

    document.getElementById('quiz-form').addEventListener('submit', (event) => {
      event.preventDefault();
      document.getElementById('result').textContent = 'Quiz submitted.';
    });
  </script>
</body>
</html>
